sites.find:
{
    ui_menu_item_t *item = controls_rebind_items;
    do {
        item->enabled = 1;
        item->activated = 0;
        ++item;
    } while (item < controls_rebind_items + 15);
}

replacements.text:
{
    unsigned char *activated =
        &controls_rebind_items[0].activated;
    do {
        activated[1] = 1;
        activated[0] = 0;
        activated += sizeof(ui_menu_item_t);
    } while ((int)activated
        < (int)&controls_rebind_items[15].activated);
}
